# Generated by Claude Fable 5.1 (Anthropic), 2026-09-15
# Fig. 3b drawn with fixed placement (matplotlib) so the canvas is filled top to bottom in every column.
# Content = fig3b_fold.py (session fish_20260913_014334): sub / join / polled-msg edges only.
import matplotlib; matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch, FancyArrowPatch, Rectangle
W, H = 2400, 900
SUB, TMR, GPU, GREY = '#F9E79F', '#AED6F1', '#d62728', '#999999'
FS_N, FS_C, FS_E, FS_L = 15, 13, 12, 16
fig = plt.figure(figsize=(W / 100, H / 100), dpi=100); ax = fig.add_axes([0, 0, 1, 1]); ax.set_xlim(0, W); ax.set_ylim(H, 0); ax.axis('off')
def box(x, y, w, h, label, kind='sub', gpu=False):
    ax.add_patch(FancyBboxPatch((x, y), w, h, boxstyle='round,pad=0,rounding_size=14', fc=SUB if kind == 'sub' else TMR,
                                ec=GPU if gpu else '#555555', lw=2.6 if gpu else 1.2))
    ax.text(x + w / 2, y + h / 2, label, ha='center', va='center', fontsize=FS_N, family='DejaVu Sans')
    return (x, y, w, h)
def cluster(x, y, w, h, title, other=False):
    ax.add_patch(FancyBboxPatch((x, y), w, h, boxstyle='round,pad=0,rounding_size=18', fc='none', ec=GREY if other else '#444444',
                                lw=1.3, ls=(0, (6, 4)) if other else '-'))
    ax.text(x + 24, y + 14, title, ha='left', va='top', fontsize=FS_C, color='#666666' if other else '#222222', family='DejaVu Sans')
def R(b): return (b[0] + b[2], b[1] + b[3] / 2)
def Lp(b): return (b[0], b[1] + b[3] / 2)
def T(b): return (b[0] + b[2] / 2, b[1])
def B(b): return (b[0] + b[2] / 2, b[1] + b[3])
def edge(p, q, label=None, rad=0.0, kind='sub', lpos=0.5, loff=(0, -14)):
    st = dict(sub=dict(color='#222222', ls='-', lw=1.6, arrowstyle='-|>', mutation_scale=16),
              join=dict(color='#1f77b4', ls=':', lw=2.2, arrowstyle='-', mutation_scale=1),
              polled=dict(color='#e07b00', ls='--', lw=2.0, arrowstyle='-|>', mutation_scale=16))[kind]
    ax.add_patch(FancyArrowPatch(p, q, connectionstyle=f'arc3,rad={rad}', shrinkA=2, shrinkB=2, **st))
    if label:
        mx, my = p[0] + (q[0] - p[0]) * lpos, p[1] + (q[1] - p[1]) * lpos
        # arc offset: perpendicular displacement of the arc3 midpoint
        dx, dy = q[0] - p[0], q[1] - p[1]; mx += -dy * rad / 2; my += dx * rad / 2
        ax.text(mx + loff[0], my + loff[1], label, ha='center', va='center', fontsize=FS_E, family='DejaVu Sans',
                bbox=dict(fc='white', ec='none', pad=1.5))
# ---- column A: legend + concatenate_data
lx, ly, lw_, lh = 12, 12, 640, 292
ax.add_patch(Rectangle((lx, ly), lw_, lh, fc='white', ec=GREY, lw=1.2))
ax.text(lx + 14, ly + 26, 'Legend', fontsize=FS_L + 1, weight='bold', va='center', family='DejaVu Sans')
rows = [('fill', SUB, 'sub', 'arrow', 'sub'), ('fill', TMR, 'tmr', 'join', 'join'), ('gpu', None, 'submits GPU work', 'polled', 'polled-msg'), ('other', None, 'other namespace', 'none', ''), ('none', None, 'hop / age: measured p50', 'none', '')]
for i, (k1, c, t1, k2, t2) in enumerate(rows):
    yy = ly + 62 + i * 46
    if k1 == 'none': ax.text(lx + 16, yy, t1, va='center', fontsize=FS_L - 1, family='DejaVu Sans'); continue
    if k1 == 'fill': ax.add_patch(Rectangle((lx + 16, yy - 14), 40, 28, fc=c, ec='none'))
    elif k1 == 'gpu': ax.add_patch(Rectangle((lx + 16, yy - 14), 40, 28, fc='none', ec=GPU, lw=2.6))
    else: ax.add_patch(Rectangle((lx + 16, yy - 14), 40, 28, fc='none', ec=GREY, lw=1.3, ls=(0, (4, 3))))
    ax.text(lx + 68, yy, t1, va='center', fontsize=FS_L, family='DejaVu Sans')
    x0 = lx + 300
    if k2 == 'arrow': ax.add_patch(FancyArrowPatch((x0, yy), (x0 + 50, yy), color='#222222', lw=1.6, arrowstyle='-|>', mutation_scale=16))
    elif k2 == 'join': ax.plot([x0, x0 + 50], [yy, yy], color='#1f77b4', ls=':', lw=2.2)
    elif k2 == 'polled': ax.add_patch(FancyArrowPatch((x0, yy), (x0 + 50, yy), color='#e07b00', lw=2.0, ls='--', arrowstyle='-|>', mutation_scale=16))
    if t2: ax.text(x0 + 62, yy, t2, va='center', fontsize=FS_L, family='DejaVu Sans')
cluster(12, 330, 640, 558, 'concatenate_data  (/sensing/lidar)', other=True)
c_right = box(40, 390, 230, 60, 'sub right cloud'); c_left = box(40, 530, 230, 60, 'sub left cloud'); c_tmr = box(40, 800, 230, 60, 'tmr 200 ms (x3)', 'tmr')
c_top = box(400, 690, 220, 60, 'sub top cloud')
# ---- column B: crop_box, common_ground, occupancy_grid_map_node
cluster(760, 12, 560, 150, 'crop_box_filter'); crop = box(800, 60, 480, 60, 'sub concatenated cloud')
cluster(760, 200, 560, 150, 'common_ground_filter'); ground = box(800, 248, 480, 60, 'sub range_cropped cloud')
cluster(760, 390, 560, 498, 'occupancy_grid_map_node  (/perception/occupancy_grid_map)', other=True)
ogm_pc = box(800, 470, 480, 60, 'sub concatenated cloud', gpu=True); ogm_sf = box(800, 790, 480, 60, 'sub single_frame cloud', gpu=True)
# ---- column C: AEB, outlier filter
cluster(1470, 12, 916, 360, 'autonomous_emergency_braking  (/control)', other=True)
aeb_tmr = box(1810, 70, 240, 60, 'tmr 100 ms', 'tmr'); aeb_sub = box(1650, 280, 560, 60, 'sub obstacle cloud (polled)')
cluster(1470, 410, 916, 478, 'occupancy_grid_based_outlier_filter'); out_sf = box(1650, 470, 560, 60, 'sub single_frame cloud'); out_map = box(1650, 790, 560, 60, 'sub occupancy map')
# ---- edges
edge(R(c_left), Lp(c_top), kind='join', rad=0.0); edge(R(c_right), Lp(c_top), kind='join', rad=0.0); edge(R(c_tmr), Lp(c_top), kind='join', rad=0.0)
ax.text(330, 640, 'join', fontsize=FS_E, color='#1f77b4', family='DejaVu Sans', bbox=dict(fc='white', ec='none', pad=1))
edge(R(c_top), Lp(crop), 'concatenated cloud', rad=-0.2, lpos=0.55, loff=(40, 30)); edge(R(c_left), Lp(crop), rad=-0.1); edge(R(c_tmr), Lp(crop), rad=-0.12)
edge(R(c_top), Lp(ogm_pc), rad=0.05); edge(R(c_left), Lp(ogm_pc), rad=0.1); edge(R(c_tmr), Lp(ogm_pc), rad=-0.15)
edge(B(crop), T(ground), 'range_cropped cloud', rad=0, loff=(150, 0))
edge((ground[0] + ground[2] - 30, ground[1] + ground[3]), (ogm_sf[0] + ogm_sf[2] - 30, ogm_sf[1]), rad=-0.16)
edge(R(ground), Lp(out_sf), 'single_frame cloud', rad=-0.05, loff=(0, -16))
edge(R(ogm_pc), Lp(out_map), 'occupancy map, hop 0.7 ms', rad=0.0, loff=(0, -16)); edge(R(ogm_sf), Lp(out_map), rad=0.0)
edge(T(out_map), B(aeb_sub), 'obstacle cloud, hop 0.2 ms', rad=0.0, loff=(0, 0))
edge(T(aeb_sub), B(aeb_tmr), 'polled-msg, age 108 ms', kind='polled', loff=(0, 0))
ax.text(1940, 415 - 4, '', fontsize=1)
for ext in ('pdf', 'png', 'svg'): fig.savefig(f'fig3b_manual.{ext}', dpi=100)
print('ok')
